const script = $('Fetch Project Script').first().json.script || '';
const questions = ($input.first().json.output && $input.first().json.output.questions) || [];

const STOP = new Set(['and','the','for','are','any','can','did','does','how','why','who','one','our','out','get','got','use','not','but','its','you','your','that','this','they','them','have','been','about','would','could','there','their','when','from','into','more','some','only','than','then','also','just','like','made','tell','what','with','was','were','has','had','will','yes','all','way','ever','anything','something']);

const toks = (s) => (s || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .split(' ')
  .filter(t => t.length >= 3 && !STOP.has(t));

const emitted = new Set();
for (const q of questions) { for (const t of toks(q.prompt_text)) emitted.add(t); }

const candidates = [];
for (const raw of script.split('\n')) {
  const trimmed = raw.trim();
  if (!/^[-*+]\s+/.test(trimmed)) continue;
  let text = trimmed.replace(/^[-*+]\s+/, '');
  text = text.replace(/\*[^*]+\*/g, ' ');
  text = text.replace(/\[Optional\]/gi, ' ');
  text = text.replace(/[*_`#]/g, ' ').replace(/\s+/g, ' ').trim();
  if (text.length < 8) continue;
  candidates.push(text);
}

const unmatched = [];
for (const c of candidates) {
  const ct = toks(c);
  if (ct.length === 0) continue;
  let hit = 0;
  for (const t of ct) { if (emitted.has(t)) hit++; }
  const cov = hit / ct.length;
  if (cov < 0.5) unmatched.push({ script_line: c, coverage: Math.round(cov * 100) / 100 });
}

return [{ json: { output: { questions }, coverage: { script_lines_checked: candidates.length, unmatched_count: unmatched.length, unmatched_script_lines: unmatched } } }];
